@Component("room-entity-projector")
public class RoomEntityProjector implements EntityProjector<Room>{
		
	// core constructor
	public RoomEntityProjector(ProjectorRegistry registry,
										RoomRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Room> getEntityClass() {
		return Room.class;
	}

    /*
	 * Insert a Room
	 * 
     * @param	entity Room
     */
    public Room create( Room entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Room
	 * 
     * @param	entity Room
     */
    public Room update( Room entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Room
	 * 
     * @param	id		UUID
     */
    public Room delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Room entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Floor
     * 
     * @param	parentId	UUID
     * @param	assignment 	Floor 
     * @return	Room
     */
    public Room assignFloor( UUID parentId, Floor assignment ) {
	    LOGGER.info("assigning Floor as " + assignment.toString() );

	    Room parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Floor.class, assignment.getFloorId());

	    // ------------------------------------------
		// assign the Floor to the parent entity
		// ------------------------------------------ 
	    parentEntity.setFloor( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Floor
	 * 
	 * @param	parentId		UUID
	 * @return	Room
	 */
	public Room unAssignFloor( UUID parentId ) {
		Room parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Floor on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Floor on the parent entithy
		// ------------------------------------------     
	    parentEntity.setFloor(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Devices
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Room
     */
    public Room addToDevices( UUID parentId, IoTDevice addTo ) {
	    LOGGER.info("handling AssignDevicesToRoomEvent - " );
	    
	    Room parentEntity = repository.findById(parentId).get();
	    IoTDevice child = registry.project( IoTDevice.class, addTo.getIoTDeviceId());
	    
	    parentEntity.getDevices().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Devices
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Room
     */
	public Room removeFromDevices( UUID parentId, IoTDevice removeFrom ) {
	    LOGGER.info("handling RemoveDevicesFromRoomEvent " );
	
	    Room parentEntity = repository.findById(parentId).get();
	    IoTDevice child = registry.project( IoTDevice.class, removeFrom.getIoTDeviceId());
	    
	    parentEntity.getDevices().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the Gateways
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Room
     */
    public Room addToGateways( UUID parentId, Gateway addTo ) {
	    LOGGER.info("handling AssignGatewaysToRoomEvent - " );
	    
	    Room parentEntity = repository.findById(parentId).get();
	    Gateway child = registry.project( Gateway.class, addTo.getGatewayId());
	    
	    parentEntity.getGateways().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Gateways
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Room
     */
	public Room removeFromGateways( UUID parentId, Gateway removeFrom ) {
	    LOGGER.info("handling RemoveGatewaysFromRoomEvent " );
	
	    Room parentEntity = repository.findById(parentId).get();
	    Gateway child = registry.project( Gateway.class, removeFrom.getGatewayId());
	    
	    parentEntity.getGateways().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Room via an FindRoomQuery
     * @return 	query	FindRoomQuery
     */
    @SuppressWarnings("unused")
    public Room find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Room - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Rooms
     *
     * @param	query	FindAllRoomQuery 
     * @return 	List<Room> 
     */
    @SuppressWarnings("unused")
    public List<Room> findAll( FindAllRoomQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Room - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final RoomRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(RoomEntityProjector.class.getName());

}
